-- Semilla del foro de EduCreator (hilos y comentarios).
-- Ejecutar a mano en MatuDB. No borra publicaciones reales:
-- solo filas cuyo id empieza por seed-post- o seed-comment-.
-- Si edu_posts o edu_comments no existen, corre primero el CREATE TABLE
-- del final de docs/migrations/edu-creator.sql.

DELETE FROM edu_comments WHERE id LIKE 'seed-comment-%';
DELETE FROM edu_posts WHERE id LIKE 'seed-post-%';


