INSERT INTO edu_posts (id, user_id, author_name, title, body, created_at) VALUES
('seed-post-01', 'seed-user-01', 'Camila Restrepo', 'El curso de SQL me ordenó la cabeza', 'Llevaba meses esquivando SQL porque en el trabajo me pasaban los reportes ya armados. Empecé la ruta el domingo y hoy escribí un SELECT con JOIN sin copiarlo de un blog. La lección de claves foráneas es la que me destrabó. Si van en lo mismo, no se salten los ejercicios del final.', NOW() - INTERVAL '360 minutes'),
('seed-post-02', 'seed-user-02', 'Andrés Felipe Gómez', 'Git dejó de darme miedo', 'Confieso que hacía git add de todo y rezaba. El curso de Git de EduCreator me hizo entender el staging, el commit y por qué no se empuja a main a lo loco. Son videos cortos y el quiz final pregunta lo que acabas de ver, no una trivia rara.', NOW() - INTERVAL '1280 minutes'),
('seed-post-03', 'seed-user-03', 'Valentina Herrera', 'Docker por fin me cuadra', 'Instalé Docker tres veces y lo borré tres veces. En la ruta por fin vi la diferencia entre imagen y contenedor sin un diagrama imposible. El ejemplo del puerto de Postgres me sirvió para levantarlo en local. Lo recomiendo si vienen de eso de en mi máquina sí funciona.', NOW() - INTERVAL '2200 minutes'),
('seed-post-04', 'seed-user-04', 'Santiago Morales', 'Cálculo con el tutor, ¿alguien más?', 'Estoy viendo límites en la ruta de cálculo y el tutor me ha sacado de dos huecos sin darme la respuesta completa. Le pedí que me explicara por qué el límite de 1 sobre x no existe en cero y me lo contó con palabras que sí entendí. ¿Alguien va en derivadas y me dice si el ritmo sigue así?', NOW() - INTERVAL '3120 minutes'),
('seed-post-05', 'seed-user-05', 'Laura Daniela Ruiz', 'Terminé el certificado de Python', 'Ayer cerré la ruta de Python y el certificado quedó con mi nombre y el código de verificación. No es un diploma de adorno: el curso sí me hizo escribir funciones, leer un CSV y fallar un quiz que después repetí en serio. Lo voy a mostrar en una postulación de analista.', NOW() - INTERVAL '4040 minutes'),
('seed-post-06', 'seed-user-06', 'Mateo Cárdenas', 'Crear un curso engancha', 'Probé el flujo de crear: le conté a EduCreator que quería un curso corto de Git para mi equipo y me armó módulos, videos y un quiz. Lo ajusté un poco en el estudio y ya lo están viendo dos compañeros. No esperaba que quedara tan usable al primer intento.', NOW() - INTERVAL '4960 minutes'),
('seed-post-07', 'seed-user-07', 'Isabella Torres', 'Los quizzes de inglés sí sirven', 'No soy de quizzes, pero el de inglés técnico me obligó a usar el vocabulario de la lección y no solo a reconocerlo. Fallé unas frases de reuniones y lo repetí al día siguiente. Hoy en una llamada di follow up sin traducir en la cabeza. Pequeño, pero real.', NOW() - INTERVAL '5880 minutes'),
('seed-post-08', 'seed-user-08', 'Juan Pablo Mejía', 'Recomendación honesta: la ruta de Git', 'Si solo van a hacer una ruta esta semana, hagan Git. Es corta, los videos no se van por las ramas y el quiz final cabe en un café. A mí me ordenó el flujo antes de meterme a Docker, y se nota.', NOW() - INTERVAL '6800 minutes'),
('seed-post-09', 'seed-user-09', 'Mariana Ospina', 'Los videos cortos me funcionan más', 'Trabajo y estudio de noche. Las lecciones de EduCreator duran lo que aguanto despierta: un concepto, un ejemplo, un cierre. Ayer vi la de listas en Python en el bus y el quiz lo hice en la casa sin sentir que había perdido el hilo. Ojalá más cursos fueran así.', NOW() - INTERVAL '7720 minutes'),
('seed-post-10', 'seed-user-10', 'Diego Alejandro Vargas', 'Pasé el quiz de joins y todavía no lo creo', 'Llevaba una semana confundiendo INNER con LEFT. Anoche hice el quiz de la ruta de SQL sin pausar el video al lado y saqué la mayoría. El que más me ayudó fue el ejercicio de clientes sin pedidos. Si están atorados en joins, hagan ese antes del quiz.', NOW() - INTERVAL '8640 minutes'),
('seed-post-11', 'seed-user-11', 'Sofía Castillo', 'Cómo usan el tutor cuando se traban', 'Pregunta seria: cuando una lección no les entra, ¿le preguntan al tutor enseguida o primero rebobinan el video? Yo lo usé en cálculo para límites y en SQL para un GROUP BY que me devolvía filas de más. En los dos casos me hizo una pregunta de vuelta en vez de soltarme el código. Me gustó, pero quiero saber si alguien tiene otra forma.', NOW() - INTERVAL '9560 minutes'),
('seed-post-12', 'seed-user-12', 'Nicolás Ramírez', 'Mi primera ruta fue Docker', 'Nunca había tocado contenedores. Empecé por la ruta de Docker porque en una oferta pedían eso y no quería llegar a inventar. La primera lección asusta menos de lo que creen. Hoy levanté el ejemplo y entendí por qué mi instalación anterior no abría el puerto.', NOW() - INTERVAL '10480 minutes'),
('seed-post-13', 'seed-user-13', 'Daniela Fernanda López', 'El certificado se ve serio', 'Terminé inglés para el trabajo y abrí el certificado. Tiene el nombre, el curso y un código para verificar. Se lo mandé a mi jefe porque en la evaluación me pidieron evidencia de inglés. No es un pantallazo de un video: se puede comprobar.', NOW() - INTERVAL '11400 minutes'),
('seed-post-14', 'seed-user-14', 'Sebastián Quintero', 'Python para alguien que viene de Excel', 'Toda la vida resolví las cosas con hojas de cálculo. Entré a la ruta de Python pensando que me iban a hablar en otro idioma. La lección de leer un CSV me enganchó porque era mi problema real: un archivo de ventas que en Excel ya no abría bien. El tutor me ayudó a entender el error de encoding sin regañarme.', NOW() - INTERVAL '12320 minutes'),
('seed-post-15', 'seed-user-15', 'Paula Andrea Jiménez', 'La lección de inglés que más me sirvió', 'De toda la ruta, la de escribir un correo para mover una reunión fue la que usé al día siguiente en el trabajo. No es gramática suelta: te da la estructura, un par de frases y un quiz donde las opciones incorrectas suenan casi bien. Esa es la que yo recomendaría si tienen poco tiempo.', NOW() - INTERVAL '13240 minutes'),
('seed-post-16', 'seed-user-16', 'Emilio Duarte', 'Dejé las diez pestañas por EduCreator', 'Antes tenía un video por aquí, un blog por allá y un cuaderno que no volvía a abrir. Llevo dos semanas en Matu AI, en las rutas de SQL y Git, y por fin el avance se queda en un solo lugar. No es magia: es que el curso, el quiz y el tutor están en la misma ruta. Lo recomiendo si se dispersan fácil, como yo.', NOW() - INTERVAL '14160 minutes'),
('seed-post-17', 'seed-user-17', 'Lucía Fernanda Peña', '¿El curso de cálculo explica límites bien?', 'Vi reseñas sueltas y no me fio. Pregunto aquí, que esto parece gente real: ¿la ruta de cálculo explica límites con ejemplos antes de soltar la definición formal? Vengo de un curso de la universidad donde nos tiraron épsilon el primer día y todavía le huyo.', NOW() - INTERVAL '15080 minutes'),
('seed-post-18', 'seed-user-18', 'Ricardo Alonso Méndez', 'Armé un curso y mis primos lo están viendo', 'Usé Crear para armar una ruta corta de inglés de viajes, se la pasé a dos primos y ya van en la tercera lección. Les gustó que cada video cierra con una idea sola y que el quiz no es eterno. Yo entré a ajustar un ejemplo que sonaba muy de libro y el estudio lo permitió sin rehacer todo.', NOW() - INTERVAL '16000 minutes'),
('seed-post-19', 'seed-user-19', 'Ana María Beltrán', 'Este foro sí se siente de clase', 'Entré a Comunidad esperando publicidad y me encontré gente contando qué lección les sirvió. Eso vale más que una landing. Voy a dejar por aquí mis notas cuando termine el módulo de índices en SQL, por si a alguien le ahorra el mismo tropiezo.', NOW() - INTERVAL '16920 minutes'),
('seed-post-20', 'seed-user-20', 'Felipe Augusto Ríos', 'SQL: la lección de índices', 'Si su consulta va bien con diez filas y se muere con diez mil, vayan a la lección de índices antes de echarle la culpa a la máquina. El video explica cuándo un índice ayuda y cuándo estorba, con un ejemplo de buscar por correo. El quiz trae un caso donde indexar de más es la respuesta incorrecta. Me gustó que no vendan el índice como magia.', NOW() - INTERVAL '17840 minutes'),
('seed-post-21', 'seed-user-21', 'Carolina Vélez', 'El quiz de Docker me pilló en volúmenes', 'Creía que tenía clara la ruta de Docker hasta el quiz. Fallé la pregunta de volúmenes: pensé que borrar el contenedor no tocaba mis datos y depende de cómo lo hayas creado. Volví a esa lección, repetí el ejercicio del Postgres y hoy sí lo puedo explicar. El quiz hizo su trabajo.', NOW() - INTERVAL '18760 minutes'),
('seed-post-22', 'seed-user-22', 'Tomás Ignacio Duarte', 'Llevo dos semanas y ya cerré tres rutas', 'SQL, Git y un repaso de inglés. No las hice en un maratón: una lección en el almuerzo y el quiz en la noche. EduCreator me sirvió porque no me suelta en un video de una hora. El certificado de Git ya lo tengo y el de SQL me falta un módulo. Si están empezando, elijan una sola ruta y termínenla. Abrir cinco a la vez fue mi primer error.', NOW() - INTERVAL '19680 minutes');
INSERT INTO edu_comments (id, post_id, user_id, author_name, body, created_at) VALUES
('seed-comment-001', 'seed-post-01', 'seed-user-02', 'Andrés Felipe Gómez', 'Me pasó igual con los reportes. La parte de WHERE contra HAVING la entendí en el segundo video, antes las mezclaba siempre.', NOW() - INTERVAL '325 minutes'),
('seed-comment-002', 'seed-post-01', 'seed-user-08', 'Juan Pablo Mejía', 'Camila, ¿cuál lección es la de las claves? Yo voy en filtros y todavía no llego ahí.', NOW() - INTERVAL '290 minutes'),
('seed-comment-003', 'seed-post-01', 'seed-user-01', 'Camila Restrepo', 'Es la que sigue después de SELECT básico. Se llama relaciones entre tablas y dura como doce minutos.', NOW() - INTERVAL '255 minutes'),
('seed-comment-004', 'seed-post-01', 'seed-user-12', 'Nicolás Ramírez', 'Yo la hice el mes pasado y hoy en el trabajo me pidieron un cruce de ventas por ciudad. Lo saqué solo.', NOW() - INTERVAL '220 minutes'),
('seed-comment-005', 'seed-post-01', 'seed-user-20', 'Felipe Augusto Ríos', 'El quiz de joins me pareció justo: pregunta lo que acabas de ver. Recomendado antes de saltar a subconsultas.', NOW() - INTERVAL '185 minutes'),
('seed-comment-006', 'seed-post-01', 'seed-user-05', 'Laura Daniela Ruiz', 'Confirmo. Venía de tutoriales sueltos y esto sí tiene orden. El certificado al final también motiva.', NOW() - INTERVAL '150 minutes'),
('seed-comment-007', 'seed-post-01', 'seed-user-23', 'Juliana Marcela Ortiz', 'A mí me sirvió repetir el ejercicio de la tabla de pedidos. La primera vez fallé el JOIN y la segunda vi el error.', NOW() - INTERVAL '115 minutes'),
('seed-comment-008', 'seed-post-01', 'seed-user-16', 'Emilio Duarte', 'Qué bueno leer esto. Iba a empezar por Python y creo que mejor abro SQL esta noche.', NOW() - INTERVAL '80 minutes'),
('seed-comment-009', 'seed-post-02', 'seed-user-06', 'Mateo Cárdenas', 'El video del área de preparación me salvó. Yo creía que commit y push eran la misma cosa.', NOW() - INTERVAL '1125 minutes'),
('seed-comment-010', 'seed-post-02', 'seed-user-14', 'Sebastián Quintero', '¿Alguien más hizo el ejercicio de la rama de prueba? Me quedé en el merge y tuve que verlo dos veces, pero valió la pena.', NOW() - INTERVAL '970 minutes'),
('seed-comment-011', 'seed-post-02', 'seed-user-02', 'Andrés Felipe Gómez', 'Sí, ese ejercicio está más adelante. Si el merge se ve raro, vuelve al minuto en el que comparan las dos ramas.', NOW() - INTERVAL '815 minutes'),
('seed-comment-012', 'seed-post-02', 'seed-user-21', 'Carolina Vélez', 'Lo recomiendo si en el trabajo les da pánico tocar el repositorio. Hoy ya abro pull requests chiquitos.', NOW() - INTERVAL '660 minutes'),
('seed-comment-013', 'seed-post-02', 'seed-user-09', 'Mariana Ospina', 'El quiz me pilló en git status. Creía que lo tenía claro y no. Menos mal se puede repetir.', NOW() - INTERVAL '505 minutes'),
('seed-comment-014', 'seed-post-02', 'seed-user-17', 'Lucía Fernanda Peña', 'Gracias, Andrés. Lo empecé anoche y la explicación de por qué no se commitea la carpeta de dependencias está clarísima.', NOW() - INTERVAL '350 minutes'),
('seed-comment-015', 'seed-post-02', 'seed-user-24', 'Gabriel Esteban Muñoz', 'Yo venía de guardar el proyecto en un zip cada viernes. Esto es otro nivel.', NOW() - INTERVAL '195 minutes'),
('seed-comment-016', 'seed-post-03', 'seed-user-10', 'Diego Alejandro Vargas', 'El ejemplo del puerto me destrabó un proyecto de la universidad. Tenía el contenedor arriba y la app apuntando al puerto equivocado.', NOW() - INTERVAL '1892 minutes'),
('seed-comment-017', 'seed-post-03', 'seed-user-13', 'Daniela Fernanda López', 'Imagen contra contenedor: lo explican con una receta y un plato. Simple, pero se queda.', NOW() - INTERVAL '1584 minutes'),
('seed-comment-018', 'seed-post-03', 'seed-user-03', 'Valentina Herrera', 'Esa analogía está en la segunda lección. Si se saltan el video corto, el resto se siente más difícil de lo que es.', NOW() - INTERVAL '1276 minutes'),
('seed-comment-019', 'seed-post-03', 'seed-user-18', 'Ricardo Alonso Méndez', '¿La ruta incluye volúmenes? En el trabajo se me borran los datos cada vez que bajo el contenedor.', NOW() - INTERVAL '968 minutes'),
('seed-comment-020', 'seed-post-03', 'seed-user-22', 'Tomás Ignacio Duarte', 'Sí incluye volúmenes, más adelante. A mí me pasó lo mismo y con esa lección dejé de perder la base de prueba.', NOW() - INTERVAL '660 minutes'),
('seed-comment-021', 'seed-post-03', 'seed-user-07', 'Isabella Torres', 'Acabo de terminar el quiz. Me equivoqué en la de redes y lo voy a repetir mañana con calma.', NOW() - INTERVAL '352 minutes'),
('seed-comment-022', 'seed-post-04', 'seed-user-17', 'Lucía Fernanda Peña', 'Voy en derivadas y sí, el ritmo se mantiene. La lección de la regla del producto es corta y el ejercicio de después es el que obliga a practicar.', NOW() - INTERVAL '2778 minutes'),
('seed-comment-023', 'seed-post-04', 'seed-user-04', 'Santiago Morales', 'Qué alivio. Tenía miedo de que después del tercer módulo se pusiera ilegible.', NOW() - INTERVAL '2436 minutes'),
('seed-comment-024', 'seed-post-04', 'seed-user-11', 'Sofía Castillo', 'Yo usé el tutor para la definición formal. Le dije que me hablara como si no hubiera visto épsilon en la vida y funcionó.', NOW() - INTERVAL '2094 minutes'),
('seed-comment-025', 'seed-post-04', 'seed-user-19', 'Ana María Beltrán', 'El video de límites laterales es el que más recomiendo. Dura poco y despeja la confusión de izquierda y derecha.', NOW() - INTERVAL '1752 minutes'),
('seed-comment-026', 'seed-post-04', 'seed-user-24', 'Gabriel Esteban Muñoz', 'Santiago, ¿el quiz de límites deja repetir? Me falta uno y no quiero quemarlo.', NOW() - INTERVAL '1410 minutes'),
('seed-comment-027', 'seed-post-04', 'seed-user-04', 'Santiago Morales', 'Sí se puede volver a intentar. Yo lo hice dos veces. La segunda ya no adiviné.', NOW() - INTERVAL '1068 minutes'),
('seed-comment-028', 'seed-post-04', 'seed-user-15', 'Paula Andrea Jiménez', 'Llegué aquí buscando cálculo y me quedo. Mañana abro la ruta.', NOW() - INTERVAL '726 minutes'),
('seed-comment-029', 'seed-post-04', 'seed-user-08', 'Juan Pablo Mejía', 'Combinar el video con una pregunta al tutor me rindió más que ver la lección tres veces seguida.', NOW() - INTERVAL '384 minutes'),
('seed-comment-030', 'seed-post-05', 'seed-user-13', 'Daniela Fernanda López', 'Felicitaciones, Laura. ¿El certificado se descarga o solo se ve en la página?', NOW() - INTERVAL '3374 minutes'),
('seed-comment-031', 'seed-post-05', 'seed-user-05', 'Laura Daniela Ruiz', 'Se puede abrir y también verificar con el código. Yo lo guardé en PDF desde el navegador para adjuntarlo.', NOW() - INTERVAL '2708 minutes'),
('seed-comment-032', 'seed-post-05', 'seed-user-01', 'Camila Restrepo', 'La lección de funciones es la que más me costó y la que más uso hoy. Si vas empezando, no la pases en acelerado.', NOW() - INTERVAL '2042 minutes'),
('seed-comment-033', 'seed-post-05', 'seed-user-20', 'Felipe Augusto Ríos', 'Yo voy en la mitad. El ejercicio de listas me gustó porque no es un hola mundo eterno.', NOW() - INTERVAL '1376 minutes'),
('seed-comment-034', 'seed-post-05', 'seed-user-09', 'Mariana Ospina', 'Qué motivador. Voy a retomar Python esta semana. Lo había dejado en variables.', NOW() - INTERVAL '710 minutes'),
('seed-comment-035', 'seed-post-06', 'seed-user-12', 'Nicolás Ramírez', '¿Le pediste el nivel o lo infirió solo? Quiero armar uno de SQL para practicantes.', NOW() - INTERVAL '4258 minutes'),
('seed-comment-036', 'seed-post-06', 'seed-user-06', 'Mateo Cárdenas', 'Le dije desde cero, para gente que solo ha usado el botón de guardar en el editor. Mientras más concreto el pedido, mejor queda el temario.', NOW() - INTERVAL '3556 minutes'),
('seed-comment-037', 'seed-post-06', 'seed-user-03', 'Valentina Herrera', 'Yo creé uno de Docker el finde y el orden de las lecciones tenía sentido. Igual cambié un título que sonaba muy de manual.', NOW() - INTERVAL '2854 minutes'),
('seed-comment-038', 'seed-post-06', 'seed-user-21', 'Carolina Vélez', 'El estudio para editar es claro. Moví una lección de lugar y no se rompió el quiz.', NOW() - INTERVAL '2152 minutes'),
('seed-comment-039', 'seed-post-06', 'seed-user-16', 'Emilio Duarte', 'Esto es lo que más me ha gustado de la plataforma. Aprender y además dejar el curso para alguien más.', NOW() - INTERVAL '1450 minutes'),
('seed-comment-040', 'seed-post-06', 'seed-user-24', 'Gabriel Esteban Muñoz', 'Mateo, ¿tus compañeros tuvieron que crear cuenta? El mío todavía no entra a la ruta que le compartí.', NOW() - INTERVAL '748 minutes'),
('seed-comment-041', 'seed-post-07', 'seed-user-15', 'Paula Andrea Jiménez', 'Ese quiz está bueno porque las opciones se parecen. No es el típico donde la respuesta correcta es la más larga.', NOW() - INTERVAL '5150 minutes'),
('seed-comment-042', 'seed-post-07', 'seed-user-09', 'Mariana Ospina', 'La lección de correos formales es la que más uso. El quiz de esa parte me corrigió el tono, no solo la gramática.', NOW() - INTERVAL '4420 minutes'),
('seed-comment-043', 'seed-post-07', 'seed-user-07', 'Isabella Torres', 'Sí. Yo también venía traduciendo todo. El video corto de reuniones es el que más recomiendo antes del quiz.', NOW() - INTERVAL '3690 minutes'),
('seed-comment-044', 'seed-post-07', 'seed-user-22', 'Tomás Ignacio Duarte', '¿Hay ruta de inglés general o solo técnico? Necesito las dos, la verdad.', NOW() - INTERVAL '2960 minutes'),
('seed-comment-045', 'seed-post-07', 'seed-user-07', 'Isabella Torres', 'La que yo hice es inglés para el trabajo: reuniones, correos y vocabulario de proyectos. No es un curso de literatura.', NOW() - INTERVAL '2230 minutes'),
('seed-comment-046', 'seed-post-07', 'seed-user-02', 'Andrés Felipe Gómez', 'Lo empecé por tu post. La primera lección es amable y el quiz no te humilla si fallas.', NOW() - INTERVAL '1500 minutes'),
('seed-comment-047', 'seed-post-07', 'seed-user-18', 'Ricardo Alonso Méndez', 'Me sirvió el ejercicio de presentarse en una daily. Lo practiqué en voz alta y el tutor me corrigió dos frases.', NOW() - INTERVAL '770 minutes'),
('seed-comment-048', 'seed-post-08', 'seed-user-03', 'Valentina Herrera', 'De acuerdo. Yo hice Docker primero y tuve que volver a Git porque no entendía por qué el repositorio se veía sucio.', NOW() - INTERVAL '5674 minutes'),
('seed-comment-049', 'seed-post-08', 'seed-user-14', 'Sebastián Quintero', '¿Cuánto te tardó completa? Tengo la noche del jueves.', NOW() - INTERVAL '4548 minutes'),
('seed-comment-050', 'seed-post-08', 'seed-user-08', 'Juan Pablo Mejía', 'Dos sentadas. Una para videos y otra para el quiz y repetir el ejercicio de ramas.', NOW() - INTERVAL '3422 minutes'),
('seed-comment-051', 'seed-post-08', 'seed-user-05', 'Laura Daniela Ruiz', 'La recomiendo también. Después de Git, Python se siente menos caótico porque ya sabes guardar el avance.', NOW() - INTERVAL '2296 minutes'),
('seed-comment-052', 'seed-post-08', 'seed-user-19', 'Ana María Beltrán', 'Gracias por el dato del orden. Iba a abrir tres rutas a la vez y mejor cierro una.', NOW() - INTERVAL '1170 minutes'),
('seed-comment-053', 'seed-post-09', 'seed-user-11', 'Sofía Castillo', 'Igual yo. El video de índices en SQL lo vi en el almuerzo y en la tarde lo apliqué en una consulta lenta.', NOW() - INTERVAL '6184 minutes'),
('seed-comment-054', 'seed-post-09', 'seed-user-01', 'Camila Restrepo', 'El formato corto es lo que me enganchó. Si duran cuarenta minutos los dejo a la mitad y no vuelvo.', NOW() - INTERVAL '4648 minutes'),
('seed-comment-055', 'seed-post-09', 'seed-user-23', 'Juliana Marcela Ortiz', '¿El reproductor guarda en qué minuto te quedaste? A veces cierro el portátil a las carreras.', NOW() - INTERVAL '3112 minutes'),
('seed-comment-056', 'seed-post-09', 'seed-user-09', 'Mariana Ospina', 'Sí, al volver me abrió donde iba. Por eso me atrevo a verlos en ratos sueltos.', NOW() - INTERVAL '1576 minutes'),
('seed-comment-057', 'seed-post-10', 'seed-user-01', 'Camila Restrepo', 'Ese ejercicio es oro. Yo también lo fallé la primera vez porque ponía el filtro en el lugar equivocado.', NOW() - INTERVAL '7412 minutes'),
('seed-comment-058', 'seed-post-10', 'seed-user-20', 'Felipe Augusto Ríos', 'INNER se queda con la intersección y LEFT conserva la tabla de la izquierda aunque no haya par. Me lo repetí hasta que dejó de sonar a trabalenguas.', NOW() - INTERVAL '6184 minutes'),
('seed-comment-059', 'seed-post-10', 'seed-user-12', 'Nicolás Ramírez', '¿El quiz muestra cuál fallaste? Quiero saber si entendí mal o si leí rápido.', NOW() - INTERVAL '4956 minutes'),
('seed-comment-060', 'seed-post-10', 'seed-user-10', 'Diego Alejandro Vargas', 'Sí, al terminar ves en cuáles te equivocaste. Yo repetí solo esas lecciones, no todo el módulo.', NOW() - INTERVAL '3728 minutes'),
('seed-comment-061', 'seed-post-10', 'seed-user-04', 'Santiago Morales', 'Lo voy a hacer el viernes. Gracias por decir el nombre del ejercicio, así no lo salto.', NOW() - INTERVAL '2500 minutes'),
('seed-comment-062', 'seed-post-10', 'seed-user-24', 'Gabriel Esteban Muñoz', 'Felicitaciones, Diego. Esos quizzes se sienten justos cuando de verdad estudiaste la lección.', NOW() - INTERVAL '1272 minutes'),
('seed-comment-063', 'seed-post-11', 'seed-user-04', 'Santiago Morales', 'Primero rebobino una vez. Si a la segunda sigo perdido, abro el tutor y le pego el punto exacto, no un ayúdame con todo.', NOW() - INTERVAL '8503 minutes'),
('seed-comment-064', 'seed-post-11', 'seed-user-17', 'Lucía Fernanda Peña', 'Eso. Mientras más precisa la pregunta, mejor responde. Yo le dije en qué minuto me perdí y me destrabó.', NOW() - INTERVAL '7446 minutes'),
('seed-comment-065', 'seed-post-11', 'seed-user-11', 'Sofía Castillo', 'En Python le pedí que no me escribiera la función, solo que me dijera qué estaba mal en mi versión. Funcionó.', NOW() - INTERVAL '6389 minutes'),
('seed-comment-066', 'seed-post-11', 'seed-user-06', 'Mateo Cárdenas', 'Cuando creé un curso, el tutor también me sirvió para reescribir una explicación que había quedado muy densa.', NOW() - INTERVAL '5332 minutes'),
('seed-comment-067', 'seed-post-11', 'seed-user-02', 'Andrés Felipe Gómez', 'Yo lo uso después del quiz, con la pregunta que fallé. Así no adelanto la respuesta.', NOW() - INTERVAL '4275 minutes'),
